export const BODY: string = "\n<p>آپ کی تصویر تیار ہے، مگر پلیٹفارم 300 DPI مانگ رہا ہے اور آپ کی فائل 72 بتاتی ہے، یا کچھ بھی نہیں بتاتی۔ مرحلے معلوم ہوں تو یہ اصلاح ایک منٹ سے بھی کم میں ہو جاتی ہے۔</p>\n<p>یہ رہنما چار عملی مرحلوں میں تصویر کا DPI بدلنا سکھاتا ہے: اپ لوڈ، قیمت چننا، بیج کی تصدیق اور ڈاؤن لوڈ۔ اس میں بیچ، اسکرین شاٹ اور وہ عام مسائل بھی شامل ہیں جن میں لوگ پھنس جاتے ہیں۔</p>\n<p>نہ کوئی سافٹ ویئر انسٹال کرنا ہے، نہ اکاؤنٹ بنانا ہے، اور نہ کوئی پکسل خراب ہوتا ہے۔ یہ تبدیلی میٹا ڈیٹا کی ترمیم ہے، اس لیے تصویر مکمل ہونے پر بالکل ویسی ہی دکھائی دیتی ہے۔</p>\n<h2 id=\"what-you-need\">شروع کرنے سے پہلے کیا چاہیے</h2>\n<p>آپ کو JPEG یا PNG فارمیٹ میں تصویری فائلیں چاہییں۔ صرف یہ دو فارمیٹ معیاری طریقے سے DPI ٹیگ محفوظ کرتے ہیں، اس لیے ٹول صرف یہی دو قبول کرتا ہے۔</p>\n<p>وہ DPI قیمت جان لیں جو آپ کی منزل مانگتی ہے۔ کتابوں کے پرنٹر اور جرنل عام طور پر 300 مانگتے ہیں، ڈرافٹ پرنٹ 150 قبول کرتا ہے اور اسکرین 72 یا 96 پر خوش رہتی ہے۔</p>\n<p>شروع کرنے سے پہلے پکسل ابعاد جانچیں۔ DPI کم پکسلوں والی تصویر کو نہیں بچا سکتا، اس لیے یقین کریں کہ ابعاد آپ کے پرنٹ سائز کے لیے کافی بڑے ہیں۔</p>\n<h2 id=\"step-1-upload\">مرحلہ 1: JPEG یا PNG فائلیں اپ لوڈ کریں</h2>\n<p><a href=\"/ur/tasveer-ka-dpi-badlein/\">Image DPI Changer</a> کھولیں اور فائلیں اپ لوڈ والے حصے میں گھسیٹ دیں۔ ایک تصویر یا پورا بیچ ایک ساتھ ڈال سکتے ہیں۔</p>\n<p>آپ اپ لوڈ والے حصے پر کلک کر کے فائلیں بھی چن سکتے ہیں، یا Ctrl+V سے کلپ بورڈ اسکرین شاٹ پیسٹ کر کے اسے فوراً مہر لگا سکتے ہیں۔</p>\n<p>ہر فائل فہرست میں اپنے موجودہ DPI کے ساتھ دکھائی دیتی ہے۔ کئی تصویروں پر Before: Not set لکھا ہوگا، جس کا مطلب صرف یہ ہے کہ فائل میں ابھی DPI ٹیگ نہیں ہے۔</p>\n<h2 id=\"step-2-choose-the-value\">مرحلہ 2: پیش سیٹ یا اپنی DPI قیمت چنیں</h2>\n<p>پانچ پیش سیٹ میں سے ایک چنیں: اسکرین کے لیے 72، ونڈوز کے لیے 96، ڈرافٹ پرنٹ کے لیے 150، اونچے پرنٹ کے لیے 300 یا آرکائیو کام کے لیے 600۔ زیادہ تر اشاعتی کام کے لیے 300 درست انتخاب ہے۔</p>\n<p>اگر آپ کی منزل کوئی اور عدد مانگتی ہے تو اسے کسٹم DPI خانے میں لکھیں۔ ایک سے 2400 تک کوئی بھی مکمل عدد قبول ہوتا ہے، اس لیے 200 یا 350 جیسی قیمتیں بھی چلتی ہیں۔</p>\n<p>ایک ہی قیمت بیچ کی ہر فائل پر لگتی ہے۔ اگر مختلف تصویروں کو مختلف DPI چاہیے تو انہیں الگ الگ بیچ میں پروسیس کریں۔ پروسیس سے پہلے عدد دوبارہ جانچیں۔</p>\n<h2 id=\"step-3-process-and-verify\">مرحلہ 3: پروسیس کریں اور تصدیق شدہ بیج دیکھیں</h2>\n<p>فائلیں پروسیس کرنے کے لیے کلک کریں۔ ٹول ہر فائل کے ہیڈر میں DPI ٹیگ دوبارہ لکھتا ہے، پھر فائل واپس پڑھ کر یقین کرتا ہے کہ نئی قیمت درست محفوظ ہوئی ہے۔</p>\n<p>ہر کامیاب فائل پر Verified DPI بیج دکھائی دیتا ہے۔ یہ بیج آپ کی تصدیق ہے کہ فائل کسی بھی معیاری ریڈر میں وہی DPI بتائے گی، بشمول آپ کے اشاعتی پلیٹفارم کے۔</p>\n<p>اگر کسی فائل پر غلطی آئے تو پیغام پڑھیں۔ خراب JPEG یا غیر معاون فارمیٹ صاف بتا دیا جائے گا، اور باقی بیچ معمول کے مطابق پروسیس ہوتا رہے گا۔ تصدیق کا مرحلہ نہ چھوڑیں۔</p>\n<h2 id=\"step-4-download\">مرحلہ 4: مہر شدہ فائلیں ڈاؤن لوڈ کریں</h2>\n<p>ہر فائل الگ ڈاؤن لوڈ کریں، یا ZIP ڈاؤن لوڈ پر کلک کر کے پورا بیچ ایک آرکائیو میں لے لیں۔ ZIP اصل فائل نام برقرار رکھتا ہے، اس لیے تصویریں سیدھا آپ کے پراجیکٹ میں واپس چلی جاتی ہیں۔</p>\n<p>آؤٹ پٹ فائلوں کے نام صاف ہوتے ہیں تاکہ اصل سے پہچانی جا سکیں۔ اصل بھی محفوظ رکھیں، تاکہ ہمیشہ اچھوتا نسخہ واپس لینے کے لیے موجود ہو۔</p>\n<p>ڈاؤن لوڈ شدہ فائل اپنے پلیٹفارم یا امیج ویور میں کھول کر DPI درست پڑھا جانا یقینی بنائیں۔ یہ آخری جانچ سیکنڈوں میں ہوتی ہے اور جمع کرانے سے پہلے غلط فہمی پکڑ لیتی ہے۔</p>\n<h2 id=\"batch-changing-dpi\">پورے بیچ کا DPI بدلنا</h2>\n<p>کتابوں، کیٹلاگ اور جرنل مضامین کو ایک ہی DPI پر درجنوں تصویریں چاہییں۔ بیچ ورک فلو ان سب کو ایک ہی بار میں ایک پیش سیٹ کے ساتھ سنبھال لیتا ہے۔</p>\n<p>پورا فولڈر ٹول میں ڈالیں اور قیمت ایک بار چنیں۔ ہر فائل مہر، تصدیق اور بیج کے ساتھ فہرست میں آتی ہے، اس لیے ایک نظر میں پتا چل جاتا ہے کہ کوئی فائل ناکام تو نہیں ہوئی۔</p>\n<p>بیچ کو ایک ZIP کے طور پر ڈاؤن لوڈ کریں۔ آرکائیو فائل نام محفوظ رکھتا ہے، جو اس وقت اہم ہے جب دستاویز یا لے آؤٹ فائل میں تصویریں نام سے حوالہ دی گئی ہوں۔</p>\n<h2 id=\"dpi-for-print-publishing\">پرنٹ اشاعت اور جرنل کے لیے DPI</h2>\n<p>Amazon KDP جیسے کتابی پلیٹفارم مخطوطے کی ہر تصویر کا DPI جانچتے ہیں۔ کم از کم سے نیچے ٹیگ والی سرورق یا اندرونی تصویر مسترد ہو جاتی ہے اور پوری جمع کرائی رک جاتی ہے۔</p>\n<p>تعلیمی جرنل اس سے بھی سخت ہوتے ہیں۔ کئی تصویروں کے لیے 300 DPI اور لائن آرٹ کے لیے 600 DPI مانگتے ہیں، اور مواد دیکھنے سے پہلے ٹیگ جانچتے ہیں۔</p>\n<p>دونوں صورتوں میں طریقہ ایک جیسا ہے: پہلے پکسل ابعاد یقینی کریں، پھر DPI مہر لگائیں، پھر بیج کی تصدیق کریں اور پھر جمع کرائیں۔ پہلا مرحلہ چھوڑنا دوسری مستردی کی سب سے عام وجہ ہے۔</p>\n<h2 id=\"fixing-a-72-dpi-file\">مسترد شدہ 72 DPI فائل ٹھیک کرنا</h2>\n<p>72 DPI والی مستردی سب سے عام DPI مسئلہ ہے، اور یہ ٹھیک کرنا سب سے آسان بھی ہے۔ پکسل عام طور پر ٹھیک ہوتے ہیں، صرف میٹا ڈیٹا ٹیگ غلط ہوتا ہے۔</p>\n<p>فائل اپ لوڈ کریں، 300 DPI پیش سیٹ چنیں اور پروسیس کریں۔ ٹول ٹیگ دوبارہ لکھتا ہے، تصدیق کرتا ہے اور ڈاؤن لوڈ شدہ فائل پلیٹفارم کی جانچ پاس کر لیتی ہے۔</p>\n<p>دوبارہ جمع کرانے سے پہلے ابعاد یقینی کریں۔ 72 DPI والی فائل اگر پکسلوں میں بھی چھوٹی ہو تو ابعاد پر دوبارہ ناکام ہوگی، اور کوئی DPI قیمت اسے ٹھیک نہیں کر سکتی۔</p>\n<h2 id=\"dpi-for-screenshots\">اسکرین شاٹ کے لیے DPI</h2>\n<p>اسکرین شاٹ DPI ٹھیک کرنا سب سے تیز ہے، کیونکہ آپ انہیں کلپ بورڈ سے سیدھا پیسٹ کر سکتے ہیں۔ اسکرین کاپی کریں، ٹول میں Ctrl+V دبائیں اور اسکرین شاٹ مہر کے لیے تیار ہے۔</p>\n<p>چھپے ہوئے دستی یا کتاب میں آنے والے اسکرین شاٹ کے لیے 300 DPI چنیں۔ پکسل وہی رہتے ہیں جو اسکرین نے پکڑے تھے، مگر ٹیگ پرنٹ ورک فلو کو مطمئن کر دے گا۔</p>\n<p>حدود کے بارے میں ایماندار رہیں۔ چھوٹے ڈائیلاگ باکس کے اسکرین شاٹ میں پکسل کم ہوتے ہیں، اور 300 DPI مہر اسے بہت چھوٹا پرنٹ بناتی ہے، تیز بڑا پرنٹ نہیں۔</p>\n<h2 id=\"removing-dpi-tags\">DPI ٹیگ ہٹانا</h2>\n<p>کبھی آپ کو مختلف ٹیگ نہیں، بلکہ کوئی ٹیگ ہی نہیں چاہیے ہوتا۔ ٹول فائل سے DPI میٹا ڈیٹا ہٹا سکتا ہے، پکسل اچھوتے رہتے ہیں۔</p>\n<p>ٹیگ ہٹانا اس وقت مفید ہے جب فائل پر غلط ٹیگ آپ کے سافٹ ویئر کو الجھا رہا ہو۔ عجیب قیمت پر ٹیگ شدہ تصویر لے آؤٹ پروگرام کو غیر متوقع پیمانہ بنا سکتی ہے، اور ٹیگ ہٹانے سے رویہ دوبارہ طے ہو جاتا ہے۔</p>\n<p>ٹیگ ہٹانے کے لیے ٹول میں remove والا انتخاب استعمال کریں اور فائل پروسیس کریں۔ ڈاؤن لوڈ شدہ فائل میں کوئی DPI میٹا ڈیٹا نہیں ہوتا، اور کھولنے والا سافٹ ویئر اپنے پہلے سے طے شدہ انداز پر چلا جاتا ہے۔</p>\n<h2 id=\"troubleshooting-formats\">غیر معاون فارمیٹ کی خرابی دور کرنا</h2>\n<p>اگر ٹول آپ کی فائل مسترد کر دے تو سب سے پہلے فارمیٹ جانچیں۔ WebP، HEIC، BMP، GIF اور SVG معاون نہیں ہیں، اور ٹول یہ صاف بتا دے گا۔</p>\n<p>فائل کو JPG یا PNG میں بدل کر دوبارہ آزمائیں۔ امیج کنورٹر WebP اور HEIC سنبھالتا ہے، اور تبدیلی پکسل محفوظ رکھتے ہوئے فائل کو ایسا فارمیٹ دیتی ہے جو DPI ٹیگ رکھ سکے۔</p>\n<p>غلط نام والی فائلوں سے ہوشیار رہیں۔ jpg ایکسٹینشن والی WebP فائل مسترد ہو جائے گی، چاہے اس کا نام درست لگے، کیونکہ ٹول اصل فائل مواد پڑھتا ہے۔</p>\n<h2 id=\"troubleshooting-corrupt-files\">خراب فائلوں کی خرابی دور کرنا</h2>\n<p>خراب JPEG غلطی کے پیغام کے ساتھ ناکام ہوگا، اور باقی بیچ پروسیس ہوتا رہے گا۔ غلطی اس فائل کی ہے، ٹول کی نہیں۔</p>\n<p>فائل پہلے امیج ویور میں کھول کر دیکھیں۔ اگر ویور بھی ناکام ہو تو فائل خراب ہے اور اسے دوبارہ ڈاؤن لوڈ یا اپنے ماخذ سے دوبارہ ایکسپورٹ کرنا ہوگا۔</p>\n<p>جو فائل ویور میں کھل جائے مگر ٹول میں ناکام ہو، اس کا ہیڈر خراب ہو سکتا ہے۔ ویور سے دوبارہ محفوظ کرنے پر تازہ ہیڈر لکھا جاتا ہے، اور نئی فائل عام طور پر ٹھیک پروسیس ہو جاتی ہے۔</p>\n<h2 id=\"checking-the-result\">ڈاؤن لوڈ کے بعد نتیجہ جانچنا</h2>\n<p>ڈاؤن لوڈ کے بعد ایک فائل کھول کر اس کا DPI یقینی کریں۔ ونڈوز پر فائل پر دایاں کلک کریں، Properties چنیں اور details ٹیب دیکھیں۔ میک پر Preview میں کھول کر انسپکٹر دیکھیں۔</p>\n<p>عدد وہی ہونا چاہیے جو آپ نے چنا تھا۔ 300 DPI پر مہر شدہ JPEG واپس 300 ہی پڑھتا ہے، جبکہ PNG 299 پڑھ سکتا ہے، کیونکہ PNG ریزولوشن پکسل فی میٹر میں محفوظ کرتا ہے۔</p>\n<p>اگر عدد غلط ہو تو ڈاؤن لوڈ شدہ فائل کی بجائے اصل فائل دوبارہ پروسیس کریں۔ مہر شدہ فائل پر دوبارہ مہر کام کرتی ہے، مگر اصل سے شروع کرنے سے تبدیلیوں کا سلسلہ صاف رہتا ہے۔</p>\n<h2 id=\"dpi-for-ecommerce\">ای کامرس اور مارکیٹ پلیس تصویروں کے لیے DPI</h2>\n<p>مارکیٹ پلیس تصویریں اسکرین پر رہتی ہیں، اس لیے DPI غیر متعلق لگتا ہے، مگر بیچنے والے پھر بھی اس میں پھنس جاتے ہیں۔ الجھن عام طور پر اس وقت شروع ہوتی ہے جب مارکیٹ پلیس کی مدد صفحہ DPI کا ذکر پکسل ابعاد کے ساتھ کرتا ہے۔</p>\n<p>مصنوعات کی فہرست کے لیے پکسل ابعاد ہی وہ اصول ہیں جو اہم ہیں۔ جو مارکیٹ پلیس سب سے لمبی طرف 1000 پکسل مانگتا ہے، وہ پکسل گنتی جانچتا ہے، DPI ٹیگ نہیں، اور صرف 600 پکسل والی 300 DPI فائل پھر بھی ناکام ہوتی ہے۔</p>\n<p>پھر بھی، مارکیٹ پلیس تصویروں پر 300 DPI مہر لگانے سے کوئی نقصان نہیں ہوتا اور کبھی کبھی فائدہ بھی ہوتا ہے۔ کچھ بیچنے والے اوزار اور پرنٹ آن ڈیمانڈ خدمات ٹیگ پڑھتی ہیں، اور درست قیمت ان ورک فلو کو ہموار رکھتی ہے۔</p>\n<h2 id=\"re-applying-different-dpi\">مختلف DPI قیمت دوبارہ لگانا</h2>\n<p>پراجیکٹ بدلتے ہیں، اور 300 DPI پر مہر شدہ فائل کو بعد میں آرکائیو یا فائن آرٹ پرنٹ کے لیے 600 DPI چاہیے ہو سکتا ہے۔ ٹول آپ کو انہی فائلوں پر نئی قیمت دوبارہ لگانے دیتا ہے۔</p>\n<p>فائلیں دوبارہ اپ لوڈ کریں، نیا پیش سیٹ یا کسٹم قیمت چنیں اور پروسیس کریں۔ ہر بار بغیر نقصان کے ہوتا ہے، اس لیے بار بار مہر سے پکسل کبھی خراب نہیں ہوتے۔</p>\n<p>آپ اس کے الٹ بھی جا سکتے ہیں، 600 سے واپس 300 پر، اسی حفاظت کے ساتھ۔ ہیڈر ہر بار دوبارہ لکھا جاتا ہے اور پکسل ڈیٹا کبھی چھوا نہیں جاتا۔</p>\n<p>DPI کا مطلب سمجھنے کے لیے مکمل پس منظر <a href=\"/ur/blog/tasveer-dpi-changer-rehnumai/\">Image DPI Changer: Complete Guide</a> میں پڑھیں، اور اسکرین PPI سے موازنے کے لیے <a href=\"/ur/blog/dpi-vs-ppi-print-web/\">DPI vs PPI: What Matters for Print and Web</a> دیکھیں۔</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"تصویر کا DPI بدلنے میں کتنا وقت لگتا ہے؟","answer":"سیکنڈوں میں۔ ٹول فائل ہیڈر میں چند بائٹ دوبارہ لکھتا ہے اور کوئی پکسل دوبارہ انکوڈ نہیں کرتا، اس لیے بڑا بیچ بھی جلد مکمل ہو جاتا ہے۔ وقت زیادہ تر اپ لوڈ اور ڈاؤن لوڈ میں لگتا ہے، پروسیسنگ میں نہیں۔"},{"question":"کیا کئی تصویروں کا DPI ایک ساتھ بدل سکتا ہوں؟","answer":"جی ہاں۔ پورا بیچ ٹول میں ڈالیں، ایک DPI قیمت چنیں اور بیچ کی ہر JPEG اور PNG فائل ایک ہی بار میں مہر ہو جاتی ہے۔ نتائج ایک ZIP فائل میں ڈاؤن لوڈ کریں، اصل فائل نام محفوظ رہتے ہیں۔"},{"question":"اگر غلطی سے کسٹم DPI لکھ دوں تو کیا ہوتا ہے؟","answer":"ٹول ایک سے 2400 تک جو عدد آپ لکھیں گے، وہی لکھ دے گا اور بیج سے تصدیق کرے گا۔ اگر غلطی نظر آ جائے تو اصل فائلیں درست قیمت کے ساتھ دوبارہ پروسیس کر لیں۔ ہر بار بغیر نقصان کے ہوتا ہے، اس لیے غلطی میں ایک منٹ ضائع ہوتا ہے، تصویر نہیں۔"},{"question":"کیا DPI بدلنے سے تصویر کی کوالٹی یا رنگ متاثر ہوتے ہیں؟","answer":"نہیں۔ صرف ہیڈر میں ریزولوشن میٹا ڈیٹا بدلتا ہے۔ پکسل، کمپریشن، EXIF ڈیٹا اور ICC کلر پروفائل بالکل ویسے ہی رہتے ہیں۔ تصویر اسکرین پر پہلے اور بعد میں ایک جیسی دکھائی دیتی ہے۔"},{"question":"کیا اسکرین شاٹ پیسٹ کر کے فوراً اس کا DPI بدل سکتا ہوں؟","answer":"جی ہاں۔ اسکرین شاٹ کاپی کریں، ٹول میں Ctrl+V دبائیں اور وہ مہر کے لیے تیار دکھائی دیتا ہے۔ پرنٹ استعمال کے لیے 300 DPI چنیں، پروسیس کریں اور نتیجہ ڈاؤن لوڈ کر لیں۔ اسکرین کیپچر سے پرنٹ تیار فائل تک یہ تیز ترین راستہ ہے۔"},{"question":"میری فائل DPI چینجر نے کیوں مسترد کر دی؟","answer":"عام وجوہات WebP یا HEIC جیسا غیر معاون فارمیٹ، سائز کی حد سے بڑی فائل یا خراب JPEG ہیں۔ غیر معاون فارمیٹ پہلے JPG یا PNG میں بدلیں، اور جو فائل امیج ویور میں نہ کھلے، اسے دوبارہ ایکسپورٹ کریں۔"}];
